var t=`0850-bhel-puri`;var n=`world-0850`;var a=`IN`;var s=`south-asia`;var r=8;var o=42;var d={en:`Bhel Puri`,ua:`Бел пурі`};var h={en:`Bhel Puri is a India dish made with poha (flattened rice), wheat noodles, roasted chickpeas, potato. This home-scale recipe assigns measured ingredients to the steps where they are used. Bhel-inspired chaat with toasted poha and crispy fried noodles: traditional puffed rice and sev are absent.`,ua:`Бел пурі, страва кухні країни Індія. Основні складники: рисові пластівці поха, пшенична локшина, смажений нут, картопля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Чаат за мотивами бел-пурі із підсмаженими пластівцями поха та хрусткою локшиною: традиційних повітряного рису й севу немає.`};var l=[{en:`Toast the poha until crisp. Separately fry the thin wheat noodles until crunchy; neither replaces genuine puffed rice or fine sev exactly.`,ua:`Підсмажте поха до хрусткості. Окремо обсмажте тонку локшину до хрускоту; це лише наближення до повітряного рису та севу.`,t:[`mixing`],m:8,i:[[`poha-flattened-rice`,220,`g`],[`wheat-noodles`,80,`g`],[`roasted-chickpeas`,80,`g`]]},{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`potato`,170,`g`],[`water`,450,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`yellow-onion`,140,`g`],[`tomato`,190,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:5,i:[[`tamarind-concentrate`,40,`g`],[`brown-sugar`,35,`g`],[`mint`,30,`g`],[`cilantro`,25,`g`],[`chaat-masala`,7,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,22,`g`],[`lemon`,1,`pcs`]]}];var c={slug:t,id:n,country:`IN`,region:s,servings:8,minutes:42,title:d,text:h,steps:l};export{a as country,c as default,n as id,o as minutes,s as region,r as servings,t as slug,l as steps,h as text,d as title};